#!/usr/bin/env node
/**
 * Migration safety guard.
 *
 * Two independent checks over prisma/migrations/<dir>/migration.sql:
 *
 * 1) Destructive statements — DROP COLUMN / DROP TABLE / TRUNCATE / DELETE FROM.
 *    They must be consciously reviewed and allowlisted.
 *
 *    Why this exists: 2026-05-30 an autogenerated `prisma migrate dev` diff
 *    bundled an unintended `ALTER TABLE "Report" DROP COLUMN "journalPhotoMediaId"`.
 *    It shipped unread, dropped the column on prod, and silently broke the
 *    reports list (a failing findMany renders as an EMPTY list, not an error).
 *    Root cause was found only in app logs, hours later.
 *
 * 2) Data-dependent DDL in migrations NEWER than 20260930000000 (2026-09-30):
 *      CREATE UNIQUE INDEX,
 *      ADD CONSTRAINT … (UNIQUE | CHECK | FOREIGN KEY),
 *      ALTER COLUMN … SET NOT NULL,
 *      ADD COLUMN … NOT NULL without DEFAULT.
 *    All four pass on the empty database CI uses but can fail on prod data
 *    (duplicate rows, NULLs, dangling references). A migration that fails
 *    mid-push leaves prod with P3009 and blocks EVERY later deploy until
 *    someone runs `prisma migrate resolve --rolled-back` by hand.
 *    Such a migration must carry a data pre-flight block
 *    (`DO $$ … IF <bad data> THEN RAISE EXCEPTION … $$`) that fails fast with
 *    a readable message, or be allowlisted in the baseline (only after the
 *    operation was checked against a copy of the prod database).
 *    Migrations older than the cutoff are already applied on prod and are
 *    not re-checked.
 *
 * SQL `--` comments never count for either check.
 *
 * To allow an intentional, reviewed migration:
 *   1. Read the migration.sql.
 *      - destructive statement: confirm the DROP/TRUNCATE/DELETE FROM is what
 *        you want. DELETE FROM removes rows — read the .sql.
 *      - data-dependent DDL: add the pre-flight block, or verify the operation
 *        on a copy of the prod database first.
 *   2. Add the migration's directory name to
 *      scripts/.migration-guard-baseline.txt
 *
 * DROP CONSTRAINT is intentionally NOT flagged — Prisma drops and recreates
 * foreign keys on almost every migration; that is not data loss.
 */
const fs = require('node:fs');
const path = require('node:path');

const MIGRATIONS_DIR = path.join(__dirname, '..', 'prisma', 'migrations');
const BASELINE_FILE = path.join(__dirname, '.migration-guard-baseline.txt');

// Migrations with a folder timestamp strictly newer than this one are checked
// for a data pre-flight block. Older folders are already applied on prod.
const GUARD_SINCE = '20260930000000';

// Data-destroying statements (case-insensitive). NOT "DROP CONSTRAINT".
const DESTRUCTIVE = /\b(DROP\s+COLUMN|DROP\s+TABLE|TRUNCATE|DELETE\s+FROM)\b/i;

// Drops SQL `--` comments; what is left is what Postgres actually runs.
function stripComments(sql) {
  return sql
    .split('\n')
    .map((line) => line.split('--')[0])
    .join('\n');
}

// Splits SQL into clauses on top-level `,` and `;` — commas inside parentheses
// or quotes (DECIMAL(14, 2), DEFAULT 'a,b') do not split.
function splitClauses(sql) {
  const parts = [];
  let cur = '';
  let depth = 0;
  let quote = false;
  for (const ch of sql) {
    if (quote) {
      cur += ch;
      if (ch === "'") quote = false;
      continue;
    }
    if (ch === "'") {
      quote = true;
      cur += ch;
      continue;
    }
    if (ch === '(') depth++;
    if (ch === ')') depth--;
    if ((ch === ',' || ch === ';') && depth === 0) {
      parts.push(cur);
      cur = '';
      continue;
    }
    cur += ch;
  }
  parts.push(cur);
  return parts;
}

// DDL that succeeds on an empty table and can fail on a populated one.
// Returns human-readable names of the operations found.
function findRiskyOperations(code) {
  const flat = code.replace(/\s+/g, ' ');
  const found = [];

  if (/\bCREATE\s+UNIQUE\s+INDEX\b/i.test(flat)) {
    found.push('CREATE UNIQUE INDEX');
  }
  if (/\bADD\s+CONSTRAINT\b[^;]*\b(UNIQUE|CHECK|FOREIGN\s+KEY)\b/i.test(flat)) {
    found.push('ADD CONSTRAINT (UNIQUE/CHECK/FOREIGN KEY)');
  }
  if (/\bALTER\s+COLUMN\b[^;]*\bSET\s+NOT\s+NULL\b/i.test(flat)) {
    found.push('ALTER COLUMN … SET NOT NULL');
  }
  // ADD COLUMN … NOT NULL без DEFAULT: у существующих строк нет значения.
  for (const clause of splitClauses(flat)) {
    if (!/\bADD\s+COLUMN\b/i.test(clause)) continue;
    if (/\bNOT\s+NULL\b/i.test(clause) && !/\bDEFAULT\b/i.test(clause)) {
      found.push('ADD COLUMN … NOT NULL без DEFAULT');
      break;
    }
  }
  return found;
}

// Rough pre-flight marker: a DO block that can RAISE EXCEPTION.
function hasPreflight(code) {
  return /\bDO\s+\$/i.test(code) && /\bRAISE\s+EXCEPTION\b/i.test(code);
}

function readBaseline() {
  if (!fs.existsSync(BASELINE_FILE)) return new Set();
  return new Set(
    fs
      .readFileSync(BASELINE_FILE, 'utf8')
      .split('\n')
      .map((l) => l.trim())
      .filter((l) => l && !l.startsWith('#'))
  );
}

const baseline = readBaseline();
const violations = [];
const risky = [];

for (const dir of fs.readdirSync(MIGRATIONS_DIR)) {
  const sqlPath = path.join(MIGRATIONS_DIR, dir, 'migration.sql');
  if (!fs.existsSync(sqlPath)) continue;
  if (baseline.has(dir)) continue;

  const raw = fs.readFileSync(sqlPath, 'utf8');
  const lines = raw.split('\n');
  lines.forEach((line, i) => {
    const code = line.split('--')[0]; // ignore SQL comments
    if (DESTRUCTIVE.test(code)) {
      violations.push({ dir, line: i + 1, text: line.trim() });
    }
  });

  const stamp = (dir.match(/^(\d{14})/) || [])[1];
  if (stamp && stamp > GUARD_SINCE) {
    const code = stripComments(raw);
    const ops = findRiskyOperations(code);
    if (ops.length > 0 && !hasPreflight(code)) {
      risky.push({ dir, ops });
    }
  }
}

if (violations.length > 0) {
  console.error('\n✖ Migration guard: destructive statement(s) in un-reviewed migration(s):\n');
  for (const v of violations) {
    console.error(`  prisma/migrations/${v.dir}/migration.sql:${v.line}`);
    console.error(`    ${v.text}`);
  }
  console.error('\nDROP COLUMN / DROP TABLE / TRUNCATE / DELETE FROM destroy data. A stray');
  console.error('autogenerated DROP COLUMN broke prod on 2026-05-30 — read the .sql');
  console.error('before pushing. DELETE FROM removes rows — read the .sql.');
  console.error('\nIf this destructive change is intentional and reviewed, add the migration');
  console.error('directory name to scripts/.migration-guard-baseline.txt, then push again.\n');
}

if (risky.length > 0) {
  console.error('\n✖ Migration guard: операция без предпроверки данных в новой миграции:\n');
  for (const r of risky) {
    console.error(`  prisma/migrations/${r.dir}/migration.sql`);
    console.error(`    ${r.ops.join('; ')}`);
  }
  console.error(`\nМиграции новее ${GUARD_SINCE} должны падать до наката, а не на боевых данных:`);
  console.error('CREATE UNIQUE INDEX / ADD CONSTRAINT (UNIQUE, CHECK, FOREIGN KEY) падают на');
  console.error('дублях и битых ссылках, SET NOT NULL — на NULL, ADD COLUMN NOT NULL без');
  console.error('DEFAULT — на непустой таблице. Упавшая миграция оставляет P3009 и глушит');
  console.error('все следующие выкладки до ручного migrate resolve --rolled-back на проде.');
  console.error('\nдобавь предпроверку данных или внеси в baseline после проверки на копии боевой базы:');
  console.error('  - блок предпроверки в том же migration.sql, например');
  console.error('      DO $$ BEGIN');
  console.error('        IF EXISTS (SELECT 1 FROM "Report" GROUP BY … HAVING count(*) > 1) THEN');
  console.error("          RAISE EXCEPTION '…';");
  console.error('        END IF;');
  console.error('      END $$;');
  console.error('  - либо строка с именем папки в scripts/.migration-guard-baseline.txt\n');
}

if (violations.length > 0 || risky.length > 0) {
  process.exit(1);
}

console.log('✓ Migration guard: no un-reviewed destructive or data-dependent migrations');
